// Writes sample device YAMLs generated by the studio so CI can run
// `esphome config` on them (see the examples job). Without YAML_OUT it only
// checks basic structure.
import { describe, expect, it } from "vitest";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { buildDeviceYaml, defaultDeviceSettings } from "../src/device";

const tm6 = JSON.parse(readFileSync(join(__dirname, "../../components/alarm_sound_detector/presets/vorwerk_thermomix_tm6_alarm.json"), "utf8"));
const dev = defaultDeviceSettings();
const samples: Record<string, string> = {
  "studio-ready-made": buildDeviceYaml(dev, [
    { id: "thermomix_tm6", ref: "vorwerk_thermomix_tm6_alarm", label: "Thermomix TM6" },
    { id: "second", ref: "thermomix_tm6", label: "Second appliance" },
  ], false),
  "studio-recording": buildDeviceYaml(dev, [], true),
  "studio-inline-preset": buildDeviceYaml(dev, [
    { id: "my_preset", ref: null, doc: { ...tm6, id: "my_preset", aliases: [] }, label: "Rice cooker" },
  ], false),
};

describe("generated device YAML", () => {
  it("has no empty component blocks and unique entity names", () => {
    for (const [name, y] of Object.entries(samples)) {
      expect(y, name).not.toMatch(/^alarm_sound_detector:\n\s*\n/m);
      const names = [...y.matchAll(/^\s+name: "([^"]+)"/gm)].map((m) => m[1]);
      expect(new Set(names).size, `${name}: ${names}`).toBe(names.length);
    }
    expect(samples["studio-recording"]).toContain("capture_server:");
    expect(samples["studio-ready-made"]).not.toContain("capture_server");
    expect(samples["studio-inline-preset"]).not.toContain("capture_server");
  });
  it("writes samples for esphome config when YAML_OUT is set", () => {
    const out = process.env.YAML_OUT;
    if (!out) return;
    mkdirSync(out, { recursive: true });
    for (const [name, y] of Object.entries(samples)) writeFileSync(join(out, `${name}.yaml`), y);
  });
});
